from __future__ import annotations

from typing import Any, Callable


class State:
    """
    Simple state container for Workpeg UI.

    This is intentionally small for v1.
    Later it can evolve into Signals, Computed values,
    server-driven state, Fabric-backed state, etc.

    Supports two usage forms:
      - Dict form (schema API):   State({"counter": 0})
      - Scalar form (compiler API): count = State(0)
    """

    def __init__(self, initial: Any = None, *, persist: bool = False):
        if isinstance(initial, dict):
            self._values: dict[str, Any] = dict(initial)
            self.default: Any = None
        else:
            self._values = {}
            self.default = initial
        # Compiler API: a persisted field is mirrored to localStorage so it
        # survives reloads (see the JS generator / runtime).
        self.persist = persist
        self._listeners: dict[str, list[Callable[[Any], None]]] = {}

    def get(self, key: str, default: Any = None) -> Any:
        return self._values.get(key, default)

    def set(self, key: str, value: Any) -> None:
        self._values[key] = value

        for listener in self._listeners.get(key, []):
            listener(value)

    def update(self, values: dict[str, Any]) -> None:
        for key, value in values.items():
            self.set(key, value)

    def subscribe(self, key: str, callback: Callable[[Any], None]) -> None:
        self._listeners.setdefault(key, []).append(callback)

    def to_schema(self) -> dict[str, Any]:
        return dict(self._values)


class Binding:
    """
    Binds a widget prop to a state key.

    Example:
        Text(Binding("counter"))
    """

    def __init__(self, key: str, default: Any = None):
        self.key = key
        self.default = default

    def resolve(self, state: State | None = None) -> Any:
        if state is None:
            return self.default

        return state.get(self.key, self.default)

    def to_schema(self) -> dict[str, Any]:
        return {
            "$binding": self.key,
            "default": self.default,
        }
